// =============================================================================
// Node: Parse Lead ID from Title
// Tujuan: Extract Bitrix Lead ID dari nama meeting TLDV.
//         Convention format meeting title: "<any prefix>_ <lead_id>"
//         Contoh: "meeting askarasoft with pt abc_ 4759"
// =============================================================================
//
// CARA UBAH REGEX (kalau format konvensi berubah):
//   Regex sekarang: /_\s*(\d+)\s*$/
//   Artinya: underscore + optional whitespace + digit(s) + optional whitespace + end-of-string
//
//   Untuk format lain:
//   - "#4759" di akhir: /#(\d+)\s*$/
//   - "[4759]" di akhir: /\[(\d+)\]\s*$/
//   - "lead:4759" di akhir: /lead:\s*(\d+)\s*$/i
//
// TRANSCRIPT sudah tersedia di webhook payload — kita ambil langsung dari sana.
// =============================================================================

const meeting = $input.item.json;
const webhookPayload = $('Webhook (TLDV Trigger)').item.json.body;

// === Extract lead_id dari meeting name ===
const meetingName = meeting.name || '';
const match = meetingName.match(/_\s*(\d+)\s*$/);
const leadId = match ? parseInt(match[1], 10) : null;
const isValid = leadId !== null && !isNaN(leadId) && leadId > 0;

// === Extract transcript dari webhook payload ===
// TLDV real payload: body.data.data adalah ARRAY of segments langsung,
// bukan object {transcript, segments}. Setiap segment: {startTime, endTime, speaker, text}.
// Fallback: kalau format lama (data.data.transcript) ada, tetap dihandle.
const rawData = webhookPayload?.data?.data;
const segments = Array.isArray(rawData)
  ? rawData
  : (rawData?.segments || []);
const transcript = Array.isArray(rawData)
  ? segments
      .map(s => (s.speaker ? `${s.speaker}: ${s.text}` : (s.text || '')))
      .filter(Boolean)
      .join('\n')
  : (rawData?.transcript || '');

// === Format attendees ===
const invitees = (meeting.invitees || [])
  .map(i => i.name ? `${i.name} (${i.email})` : i.email)
  .filter(Boolean)
  .join(', ') || '(tidak ada data)';

const organizer = meeting.organizer
  ? `${meeting.organizer.name || meeting.organizer.email}`
  : '(tidak diketahui)';

// === Format duration ke menit ===
const durationMinutes = meeting.duration
  ? Math.round(meeting.duration / 60)
  : 0;

return {
  json: {
    meeting_id: meeting.id,
    meeting_name: meetingName,
    lead_id: leadId,
    is_valid: isValid,
    error_reason: isValid ? null : `Meeting title "${meetingName}" tidak match pola "..._<digits>"`,
    happened_at: meeting.happenedAt,
    duration_minutes: durationMinutes,
    organizer: organizer,
    attendees: invitees,
    tldv_url: meeting.url,
    transcript: transcript,
    transcript_length: transcript.length,
    segment_count: segments.length
  }
};

// =============================================================================
// Node: Log Skip Reason (Error Branch)
// Tujuan: Log alasan workflow skip (bukan error crash), supaya di execution log
//         terlihat kenapa comment tidak ter-post.
//
// Skip scenarios:
//   - Meeting title tidak match regex → lead_id null
//   - Lead ID tidak ada di Bitrix (deleted / typo)
//
// Kalau mau notif ke channel eksternal (Telegram/email), tambah HTTP node
// setelah node ini (misal ke Telegram Bot API).
// =============================================================================

const parseData = $('Parse Lead ID from Title').item?.json || {};
const leadGetResponse = $input.item?.json || {};

const reason = !parseData.is_valid
  ? `Meeting title parse failed: "${parseData.meeting_name}" tidak match pola "..._<digits>"`
  : !leadGetResponse.result?.ID
    ? `Lead #${parseData.lead_id} tidak ditemukan di Bitrix`
    : 'Unknown skip reason';

console.log('[TLDV Meeting Summary SKIP]', {
  meeting_id: parseData.meeting_id,
  meeting_name: parseData.meeting_name,
  attempted_lead_id: parseData.lead_id,
  reason: reason
});

return {
  json: {
    skipped: true,
    reason: reason,
    meeting_id: parseData.meeting_id,
    meeting_name: parseData.meeting_name
  }
};

// =============================================================================
// Node: Parse Classifier Response
// Tujuan: Extract JSON dari AI response, safe fallback ke should_create=false
//         kalau AI down atau return invalid JSON.
//         Enrich dengan lead_id + assigned_by_id untuk downstream Bitrix Add.
// =============================================================================

const input = $input.item.json;
const leadData = $('Bitrix: Get Lead (validate)').item?.json?.result || {};
const leadId = $('Parse Lead ID from Title').item.json.lead_id;

// Fallback response (used if anything fails)
const fallback = {
  should_create: false,
  reason: 'Classifier failed (default skip)',
  suggested_title: '',
  lead_id: leadId,
  assigned_by_id: parseInt(leadData.ASSIGNED_BY_ID) || 1
};

// Path 1: HTTP node errored (choices missing, or error field present)
if (!input.choices || input.error) {
  fallback.reason = 'Classifier AI call failed: ' + JSON.stringify(input.error || input).substring(0, 300);
  return { json: fallback };
}

// Path 2: Extract content string
const content = input.choices?.[0]?.message?.content || '';

// Parse JSON (strip markdown fences if AI adds them)
let parsed;
try {
  const cleaned = content.replace(/```json\s*/g, '').replace(/```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  fallback.reason = 'AI returned invalid JSON. Raw: ' + content.substring(0, 300);
  return { json: fallback };
}

// Success path: return normalized decision
return {
  json: {
    should_create: parsed.should_create === true,
    reason: parsed.reason || '',
    suggested_title: parsed.suggested_title || `Proposal - ${leadData.TITLE || 'Untitled'}`,
    lead_id: leadId,
    assigned_by_id: parseInt(leadData.ASSIGNED_BY_ID) || 1
  }
};

// =============================================================================
// Node: Log Proposal Result
// Tujuan: Comprehensive log SEMUA path (skipped/success/error) untuk troubleshooting.
//         Input bisa dari 2 upstream:
//           - IF Should Create? false branch: {should_create:false, reason, ...}
//           - Bitrix Add SPA HTTP output (success or error with onError=continue)
// =============================================================================

const input = $input.item.json;
const parseData = $('Parse Lead ID from Title').item?.json || {};
const classifyData = $('Parse Classifier Response').item?.json || {};

let path, details;

if (input.should_create === false) {
  // Came from IF false branch
  path = 'skipped';
  details = { reason: input.reason };
} else if (input.result?.item?.id) {
  // Came from Add SPA HTTP success
  path = 'success';
  details = {
    spa_item_id: input.result.item.id,
    title: input.result.item.title,
    lead_id: classifyData.lead_id
  };
} else {
  // Came from Add SPA HTTP error (onError=continueRegularOutput passed error through)
  path = 'error';
  details = {
    reason: 'crm.item.add failed',
    response: JSON.stringify(input).substring(0, 500),
    attempted_title: classifyData.suggested_title,
    attempted_lead_id: classifyData.lead_id,
    attempted_assigned_by: classifyData.assigned_by_id
  };
}

console.log(`[TLDV Proposal ${path.toUpperCase()}]`, {
  meeting_id: parseData.meeting_id,
  meeting_name: parseData.meeting_name,
  classifier_reason: classifyData.reason,
  ...details
});

return {
  json: {
    logged: true,
    path,
    ...details
  }
};
